sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var startVal = g_form.getValue('start_date');
    var endVal   = g_form.getValue('end_date');
    if (!startVal || !endVal) {
        return;
    }
    var startMs = getDateFromFormat(startVal, g_user_date_format);
    var endMs   = getDateFromFormat(endVal,   g_user_date_format);
    if (startMs === 0 || endMs === 0) {
        return;
    }
    g_form.hideFieldMsg('end_date', true);
    g_form.clearMessages();                       // remove an old banner first
    if (endMs < startMs) {
        g_form.clearValue('end_date');            // clear FIRST
        //g_form.addErrorMessage('End Date cannot be earlier than Start Date.');  // form banner
        setTimeout(function () {                  // then the inline message, after the re-render
            g_form.showFieldMsg('end_date', 'End Date cannot be earlier than Start Date.', 'error');
        }, 100);
    }
}
